"use client";
import {useEffect,useRef,useState,type FormEvent} from "react";
type Option={slug:string;name:string};
type Course=Option&{programSlug:string|null;branchSlug:string|null};
type Initial={program:string;branch:string;course:string;schoolClass:string};
export function ConsultationForm({programs,branches,initial,initialNote=""}:{initialNote?:string;programs:Option[];branches:Option[];initial:Initial}){
 const [program,setProgram]=useState(initial.program),[branch,setBranch]=useState(initial.branch),[course,setCourse]=useState(initial.course),[schoolClass,setSchoolClass]=useState(initial.schoolClass);
 const [courses,setCourses]=useState<Course[]>([]),[classes,setClasses]=useState<Option[]>([]),[optionsError,setOptionsError]=useState(""),[revision,setRevision]=useState(0),[loadingCourses,setLoadingCourses]=useState(false),[loadingClasses,setLoadingClasses]=useState(false);
 const [busy,setBusy]=useState(false),[error,setError]=useState(""),[success,setSuccess]=useState(false);
 const attempt=useRef<{payload:string;key:string}|null>(null),message=useRef<HTMLDivElement>(null);
 async function options(query:URLSearchParams,signal:AbortSignal){const list:Course[]=[];for(let page=0;page<=10000;page++){query.set("page",String(page));const r=await fetch("/api/catalog?"+query,{signal,cache:"no-store"});if(!r.ok)throw Error();const data=await r.json();list.push(...data.items);if(!data.hasNext)return list;}throw Error();}
 useEffect(()=>{const abort=new AbortController();setOptionsError("");setCourses([]);if(!program||!branch){setLoadingCourses(false);return ()=>abort.abort();}setLoadingCourses(true);options(new URLSearchParams({kind:"COURSE",program,branch}),abort.signal).then(list=>{setCourses(list);if(course&&!list.some(c=>c.slug===course)){setCourse("");setSchoolClass("");}}).catch(()=>{if(!abort.signal.aborted){setCourse("");setSchoolClass("");setOptionsError("Chưa tải được khóa học. Bạn vẫn có thể gửi yêu cầu tư vấn theo chương trình.");}}).finally(()=>{if(!abort.signal.aborted)setLoadingCourses(false);});return ()=>abort.abort();},[program,branch,revision]);
 useEffect(()=>{const abort=new AbortController();setClasses([]);if(!course||!branch){setLoadingClasses(false);return ()=>abort.abort();}setLoadingClasses(true);options(new URLSearchParams({kind:"CLASS",course,branch}),abort.signal).then(setClasses).catch(()=>{if(!abort.signal.aborted)setOptionsError("Chưa tải được lớp học. Bạn vẫn có thể gửi yêu cầu tư vấn theo khóa học.");}).finally(()=>{if(!abort.signal.aborted)setLoadingClasses(false);});return ()=>abort.abort();},[course,branch,revision]);
 useEffect(()=>{if(error||success)message.current?.focus();},[error,success]);
 async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();if(busy)return;const form=e.currentTarget;if(!form.reportValidity())return;const d=new FormData(form);
  const payload=JSON.stringify({fullName:String(d.get("fullName")||"").trim(),phone:String(d.get("phone")||"").trim(),email:String(d.get("email")||"").trim()||null,branchSlug:branch,programSlug:program||null,courseSlug:course||null,classSlug:schoolClass||null,note:String(d.get("note")||"").trim()||null,consent:d.get("consent")==="on",website:String(d.get("website")||"")});
  if(!attempt.current||attempt.current.payload!==payload)attempt.current={payload,key:crypto.randomUUID()};setBusy(true);setError("");
  try{const r=await fetch("/api/consultations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({...JSON.parse(payload),requestId:attempt.current.key}),signal:AbortSignal.timeout(15000)});const data=await r.json();if(r.status!==202){if(r.status===409)attempt.current=null;throw Error(data.message||"Chưa thể gửi yêu cầu. Vui lòng thử lại.");}setSuccess(true);}catch(e){setError(e instanceof Error&&e.name!=="TimeoutError"&&e.name!=="TypeError"?e.message:"Kết nối bị gián đoạn. Vui lòng gửi lại; thông tin đã nhập vẫn được giữ.");}finally{setBusy(false);}
 }
 if(success)return <div className="formSuccess" ref={message} tabIndex={-1} role="status"><span className="successIcon" aria-hidden>✓</span><p className="eyebrow">ĐÃ GHI NHẬN YÊU CẦU</p><h2>Cảm ơn bạn đã quan tâm.</h2><p>Đội ngũ tư vấn tại <strong>{branches.find(b=>b.slug===branch)?.name}</strong> sẽ liên hệ qua số điện thoại bạn cung cấp.</p><p>Bạn chưa cần tạo tài khoản hoặc thanh toán ở bước này.</p><button className="button light" onClick={()=>{setSuccess(false);attempt.current=null;}}>Gửi yêu cầu khác</button></div>;
 return <form className="consultationForm" onSubmit={submit} aria-busy={busy}><div className="formIntro"><p className="eyebrow">ĐĂNG KÝ TƯ VẤN</p><h2>Để lại thông tin, chúng tôi sẽ liên hệ.</h2><p>Các trường có dấu * là bắt buộc.</p></div>
 {error&&<div role="alert" className="formError" tabIndex={-1} ref={message}>{error}</div>}
 {!branches.length&&<div className="formHint" role="status">Thông tin chi nhánh tiếp nhận đang được cập nhật. Vui lòng quay lại sau hoặc liên hệ trung tâm qua kênh chính thức.</div>}
 <fieldset disabled={busy||!branches.length}><legend className="srOnly">Thông tin liên hệ và nhu cầu học</legend><div className="formGrid"><label>Họ và tên *<input name="fullName" required minLength={2} maxLength={100} autoComplete="name" placeholder="Nhập họ và tên"/></label><label>Số điện thoại di động *<input name="phone" type="tel" required maxLength={30} autoComplete="tel" inputMode="tel" placeholder="Ví dụ: 0901234567"/></label><label className="fullWidth">Email <span className="optional">(không bắt buộc)</span><input name="email" type="email" maxLength={150} autoComplete="email" placeholder="Địa chỉ email của bạn"/></label><label>Chi nhánh mong muốn *<select name="branch" required value={branch} onChange={e=>{setBranch(e.target.value);setSchoolClass("");}}><option value="">Chọn chi nhánh</option>{branches.map(b=><option value={b.slug} key={b.slug}>{b.name}</option>)}</select></label><label>Chương trình quan tâm<select name="program" value={program} onChange={e=>{setProgram(e.target.value);setCourse("");setSchoolClass("");}}><option value="">Tôi cần được tư vấn thêm</option>{programs.map(p=><option key={p.slug} value={p.slug}>{p.name}</option>)}</select></label><label>Khóa học<select name="course" value={course} disabled={!program||!branch||loadingCourses} onChange={e=>{setCourse(e.target.value);setSchoolClass("");}}><option value="">{loadingCourses?"Đang tải khóa học…":"Nhờ trung tâm tư vấn khóa phù hợp"}</option>{courses.map(c=><option key={c.slug} value={c.slug}>{c.name}</option>)}</select></label><label>Lớp học<select name="schoolClass" value={schoolClass} disabled={!course||loadingClasses} onChange={e=>setSchoolClass(e.target.value)}><option value="">{loadingClasses?"Đang tải lớp học…":"Tư vấn lịch học phù hợp"}</option>{classes.map(c=><option key={c.slug} value={c.slug}>{c.name}</option>)}</select></label><label className="fullWidth">Bạn mong muốn điều gì?<textarea name="note" defaultValue={initialNote} rows={3} maxLength={1000} placeholder="Mục tiêu học tập, thời gian thuận tiện hoặc điều bạn muốn hỏi…"/></label></div>
 {optionsError&&<div className="formHint" role="status">{optionsError} <button className="inlineButton" type="button" onClick={()=>setRevision(v=>v+1)}>Tải lại danh sách</button></div>}
 <label className="websiteTrap" aria-hidden="true">Website<input name="website" tabIndex={-1} autoComplete="off"/></label>
 <label className="consent"><input name="consent" type="checkbox" required/><span>Tôi đồng ý để trung tâm sử dụng thông tin đã cung cấp để liên hệ tư vấn theo <a href="/chinh-sach-bao-mat" target="_blank" rel="noopener noreferrer">chính sách thông tin</a>. *</span></label><button className="button submitButton" type="submit" disabled={!branches.length||busy||loadingCourses||loadingClasses}>{busy?"Đang gửi yêu cầu…":"Gửi yêu cầu tư vấn →"}</button><p className="formHint">Đăng ký tư vấn không đồng nghĩa với ghi danh hoặc giữ chỗ trong lớp.</p></fieldset></form>;
}

